; King's Quest I (SCI remake), Korean UTF-8 translation. One map; the same three faces
; in every render_target (1 bpp, hard-edged, so no preset differs).
;
; Faces, picked by the game's font id (the user's pairing selection, 2026-10-15):
;   status - font 0 (status line, menu bar, parser line): HTERM16.SVF, hanterm h01.bdf
;            16 px, jamo layout 844 (a jamo set, all 11,172 syllables);
;   ui     - font 4 (the title menu's buttons), font 999 and any other id: IYAGI16.SVF,
;            Iyagi IYG.KOR (san-1.0's font-kor) 16 px, a jamo set (lossless);
;   body   - font 300 (message boxes, narration): MUNJO24.SVF, Mac HangulTalk Munjo
;            24 px, the mac-fbit-45sets jamo set.
; English (every id) is the game's own font: range.basic-latin=original, advances and
; origin from the game. HTERM16 and IYAGI16 carry ASCII but it is not used; MUNJO24 has
; no ASCII at all. KQ1's text uses no non-ASCII character other than Hangul.
; The game draws at 320x200 and the map doubles it (scale=2): the 16 px cell is the
; engine's default layout cell (the 8-row status/menu line); font 300 sets size=24
; cell=glyph so the layout cell is the face's 24 px (the 12-row message line) -
; without that the engine keeps its 16 px cell and draws the 24 px glyph 4 px off
; its pen, overlapping its neighbours. Text wraps by the game's pixel width.
; Licences: HTERM.TXT, IYAGI (SAN10.TXT), MUNJO.TXT beside this file.
; Fallback: SANGAM16.SVF (engine data, 20 KB) is the last face of every chain whose faces live in the
; jamo font pack, so a missing font pack still shows Korean (16 px; see SAN10.TXT).
[map]
version=2

[render]
scale=2
blend=off

[fonts]
hterm=HTERM16.SVF
ui=IYAGI16.SVF
munjo=MUNJO24.SVF
fb=SANGAM16.SVF

[font]
face=ui,fb
missing=u+25a1
align=cell
; English in the game's own font
range.basic-latin=original

[font.0]
face=hterm,fb

[font.300]
face=munjo,fb
size=24
cell=glyph
